"""Exact invariant charge metric and ROC-slack barrier for the QC seed cone.

This is a limitation of convex/symmetry/translation closure of the 4096
seed, not a limitation of QC itself and not a compatible separation.
"""
from pathlib import Path
from fractions import Fraction as R
from math import factorial
import importlib.util,json,sys,time
root=Path(__file__).resolve().parents[1];sp=importlib.util.spec_from_file_location('compat',root/'outputs/gradient_compatibility/receive.py');g=importlib.util.module_from_spec(sp);sp.loader.exec_module(g);d=g.gauge();b,ca,r=g.b,g.ca,g.r;start=time.perf_counter();qc=json.loads((root/'outputs/quadratic_boundary/certificate.json').read_text());ac=json.loads((root/'outputs/acoustic_capacity/certificate.json').read_text());op=[list(map(R,row)) for row in qc['normal_form_operator']];jet=[list(map(R,row)) for row in ac['jet_operator_on_normal_basis']];charge=ca.mm(jet,op);TM=d['translations'];U=d['charge_representatives'];powers=d['powers'];weights=[R(__import__('math').prod(factorial(n) for n in pw),factorial(3)) for pw in powers];D=[[weights[i]*R(int(i==j)) for j in range(20)] for i in range(20)];TG=ca.mm(ca.transpose(TM),ca.mm(D,TM));b.pd(TG);proj,_=ca.solve_range(TG,ca.mm(ca.transpose(TM),ca.mm(D,U)));E=ca.add(U,ca.scale(ca.mm(TM,proj),-1));assert ca.mm(ca.transpose(TM),ca.mm(D,E))==[[0]*8 for _ in range(4)];M=ca.mm(ca.transpose(E),ca.mm(D,E));b.pd(M);assert ca.mm(charge,E)==[[R(int(i==j)) for j in range(8)] for i in range(8)]
EP=[{tuple(pw):E[k][j] for k,pw in enumerate(powers) if E[k][j]} for j in range(8)];A=[b.var(4,i) for i in range(4)];JA=[b.scale(A[2],-1),b.scale(A[3],-1),A[0],A[1]];LG=[b.add(*(b.mul(b.diff(P,i),JA[i]) for i in range(4))) for P in EP];GG=[b.transform(P,(3,2,1,0),(1,-1,1,-1)) for P in EP];LM=ca.transpose([[P.get(tuple(pw),R(0)) for pw in powers] for P in LG]);GM=ca.transpose([[P.get(tuple(pw),R(0)) for pw in powers] for P in GG]);L=ca.mm(charge,LM);G=ca.mm(charge,GM)
assert ca.add(ca.mm(ca.transpose(L),M),ca.mm(M,L))==[[0]*8 for _ in range(8)];assert ca.mm(ca.transpose(G),ca.mm(M,G))==M
F,C0,T=r.m.acquired();cv=[C0.get(tuple(pw),R(0)) for pw in powers];z0=[g.dot(row,cv) for row in charge];m0=g.quadratic(M,z0);assert m0>0
u=list(map(R,qc['lower_rank_one_output']));xi=list(map(R,qc['lower_rank_one_spatial']));R0=[u[i]*xi[j] for i in range(2) for j in range(2)];H=[[b.evaluate(P,R0) for P in row] for row in d['HF']];b.pd(H);dc=[b.evaluate(b.diff(C0,i),R0) for i in range(4)];hh=r.m.linear_solve(H,dc);nu_lower=g.dot(dc,hh)/(2*g.dot(R0,R0));assert R(1858)<nu_lower<R(1859);gap=R(4096-1859);threshold=gap+nu_lower;assert threshold>4095
# A concrete diagnostic of the exact completed-slack convexity identity.
# Kernel factors use the retained twelve-dimensional normal coordinates.
sys.path.insert(0,str(root/'outputs/acoustic_capacity'));ks=importlib.util.spec_from_file_location('kernel',root/'outputs/acoustic_capacity/kernel.py');km=importlib.util.module_from_spec(ks);ks.loader.exec_module(km);W=km.capacity_kernel(R0);coords=[g.dot(row,cv) for row in op];hv=[R(1),R(-2),R(3),R(-1)];c1=[v for v in coords];c2=[R(-2)*v for v in coords];c2[:4]=[v+x for v,x in zip(c2[:4],hv)];alpha=R(2,5);mean=[alpha*x+(1-alpha)*y for x,y in zip(c1,c2)];variance=alpha*g.quadratic(W,[x-y for x,y in zip(c1,mean)])+(1-alpha)*g.quadratic(W,[x-y for x,y in zip(c2,mean)]);assert variance>=0 and alpha*g.quadratic(W,c1)+(1-alpha)*g.quadratic(W,c2)-g.quadratic(W,mean)==variance
out={'coefficient_metric':'Bombieri cubic tensor metric, weights prod(alpha!)/3!','bombieri_weights':list(map(str,weights)),'unit_charge_section':[[str(v) for v in row] for row in ca.transpose(E)],'invariant_charge_metric':[[str(v) for v in row] for row in M],'output_rotation_charge_generator':[[str(v) for v in row] for row in L],'Gamma_charge_action':[[str(v) for v in row] for row in G],'C0_charge':list(map(str,z0)),'C0_charge_squared_norm':str(m0),'seed_QC_coefficient':4096,'globally_ROC_comparator_coefficient':1859,'uniform_seed_completed_ROC_slack':4474,'exact_lower_ROC_direction':list(map(str,R0)),'exact_scalar_ROC_lower_bound':str(nu_lower),'generated_cone_C0_scalar_coefficient_lower_bound':str(threshold),'scope':'Convex combinations, argument translations, F-preserving rotations and Gamma, scalar rescaling, addition of QC quadratics, affine/determinant gauges, and coefficientwise limits of the acquired 4096 seed. Does not restrict QC proofs outside this generated cone.','genuine_ROC_QC_separation':False,'seconds':time.perf_counter()-start};(root/'work/closure_barrier.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'invariant_metric_PD':True,'continuous_output_invariance_exact':True,'Gamma_invariance_exact':True,'nontranslation_charge_positive':True,'generated_C0_scalar_coefficient_lower_bound':float(threshold),'exact_slack_variance_identity':True,'genuine_separation':False,'seconds':time.perf_counter()-start},indent=2),flush=True)
